using Cosmos.Application.Abstractions.Persistence;
using Cosmos.Contracts.Common;
using Cosmos.Contracts.HsnGst;
using Cosmos.Persistence.Connection;
using Cosmos.Persistence.Dapper;
namespace Cosmos.Persistence.Repositories;
public sealed class HsnGstRepository(ISqlConnectionFactory factory) : IHsnGstRepository
{
    public async Task<PagedResult<HsnSacDto>> GetHsnSacsAsync(HsnSacListQuery q,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);var r=await StoredProcedureExecutor.QueryAsync<HsnSacDto>(c,"usp_HsnSac_List",q,ct);return new(r,q.PageNumber,q.PageSize,r.FirstOrDefault()?.TotalCount??0);}
    public async Task<HsnSacDto?> GetHsnSacAsync(long id,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);return await StoredProcedureExecutor.QuerySingleOrDefaultAsync<HsnSacDto>(c,"usp_HsnSac_Get",new{Id=id},ct);}
    public async Task<HsnSacDto> SaveHsnSacAsync(long? id,SaveHsnSacRequest r,long? u,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);return await StoredProcedureExecutor.QueryWithStatusAsync<HsnSacDto>(c,"usp_HsnSac_Save",new{Id=id,r.Code,r.CodeType,r.Description,r.IsActive,UserId=u},ct);}
    public async Task<PagedResult<GstRateRuleVersionDto>> GetRateVersionsAsync(GstRateRuleVersionListQuery q,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);var r=await StoredProcedureExecutor.QueryAsync<GstRateRuleVersionDto>(c,"usp_GstRateRuleVersion_List",q,ct);return new(r,q.PageNumber,q.PageSize,r.FirstOrDefault()?.TotalCount??0);}
    public async Task<GstRateRuleVersionDto> SaveRateVersionAsync(SaveGstRateRuleVersionRequest r,long? u,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);return await StoredProcedureExecutor.QueryWithStatusAsync<GstRateRuleVersionDto>(c,"usp_GstRateRuleVersion_Save",new{r.RuleCode,r.TotalRate,r.EffectiveFrom,r.EffectiveTo,r.IsActive,r.Notes,UserId=u},ct);}
    public async Task SaveCategoryDefaultAsync(long id,SaveCategoryHsnDefaultRequest r,long? u,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);await StoredProcedureExecutor.ExecuteStatusAsync(c,"usp_CategoryHsnDefault_Save",new{CategoryId=id,r.HsnSacId,r.EffectiveFrom,r.EffectiveTo,UserId=u},ct);}
    public async Task SaveItemOverrideAsync(long id,SaveItemHsnOverrideRequest r,long? u,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);await StoredProcedureExecutor.ExecuteStatusAsync(c,"usp_ItemHsnOverride_Save",new{ItemId=id,r.HsnSacId,r.EffectiveFrom,r.EffectiveTo,UserId=u},ct);}
    public async Task<EffectiveHsnMappingDto?> GetEffectiveCategoryDefaultAsync(long id,DateOnly d,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);return await StoredProcedureExecutor.QuerySingleOrDefaultAsync<EffectiveHsnMappingDto>(c,"usp_CategoryHsnDefault_GetEffective",new{CategoryId=id,OnDate=d},ct);}
    public async Task<EffectiveHsnMappingDto> RetireCategoryDefaultAsync(long categoryId,long mappingId,RetireHsnMappingRequest r,long? u,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);return await StoredProcedureExecutor.QueryWithStatusAsync<EffectiveHsnMappingDto>(c,"usp_CategoryHsnDefault_Retire",new{CategoryId=categoryId,MappingId=mappingId,r.EffectiveTo,UserId=u},ct);}
    public async Task<EffectiveHsnMappingDto> RetireItemOverrideAsync(long itemId,long mappingId,RetireHsnMappingRequest r,long? u,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);return await StoredProcedureExecutor.QueryWithStatusAsync<EffectiveHsnMappingDto>(c,"usp_ItemHsnOverride_Retire",new{ItemId=itemId,MappingId=mappingId,r.EffectiveTo,UserId=u},ct);}
    public async Task<EffectiveProductClassificationDto> GetEffectiveClassificationAsync(long id,DateOnly d,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);return await StoredProcedureExecutor.QuerySingleOrDefaultAsync<EffectiveProductClassificationDto>(c,"usp_ItemHsn_Resolve",new{ItemId=id,OnDate=d},ct) ?? new EffectiveProductClassificationDto(id,null,null,null,null,null,"Missing",null,null,null);}
}
